def re_arrange(arr, n):
    pos = []
    neg = []
    for i in range(n):
        if arr[i] >= 0:
            pos.append(arr[i])
        else:
            neg.append(arr[i])

    result = []
    pos_idx = 0
    neg_idx = 0
    while pos_idx < len(pos) and neg_idx < len(neg):
        result.append(neg[neg_idx])
        result.append(pos[pos_idx])
        pos_idx += 1
        neg_idx += 1

    if pos_idx < len(pos):
        result.extend(pos[pos_idx:])
    elif neg_idx < len(neg):
        result.extend(neg[neg_idx:])

    return result

